/// <summary>
/// This is an extension class for <c>WMSPickingRegistration</c> form WMSPickingRoute datasource.
/// </summary>
[ExtensionOf(formDataSourceStr(WMSPickingRegistration, WMSPickingRoute))]
final class METWMSPickingRegistrationDS_Extension
{
}

Method.Source:
/// <summary>
/// Enable or disable the print button based on transaction type.
/// </summary>
/// <returns>Integer</returns>
public int active()
{
    int ret;

    ret = next active();

    FormControl ctrl = this.formRun().design().controlName(formControlStr(WMSPickingRegistration, PrintMenuButton));
    WMSPickingRoute wmsPickingRoute = this.cursor();

    if (wmsPickingRoute.transType == InventTransType::Sales)
    {
        ctrl.visible(true);
    }
    else
    {
        ctrl.visible(false);
    }

    return ret;
}

/// <summary>
/// Handles selection changes in the WMSPickingRoute data source.
/// Iterates through selected records and enables or disables the PickQtyUpdateButton
/// based on transaction type and expedition status.
/// </summary>
public void selectionChanged()
{
    WMSOrderTrans  wmsOrderTrans;
    InventDim      inventDim;
    InventLocation inventLocation;

    next selectionChanged();

    boolean canReviewSelection = true;

    FormControl ctrl = this.formRun().design().controlName(formControlStr(WMSPickingRegistration, PickQtyUpdateButton));

    FormDataSource  WMSPickingRouteDS = this;

    WMSPickingRoute currentLine = WMSPickingRouteDS.getFirst(1) ?
                                WMSPickingRouteDS.getFirst(1) :
                                WMSPickingRouteDS.cursor();

    if (!currentLine)
    {
        canReviewSelection = false;
    }

    while (currentLine && canReviewSelection)
    {
        if (currentLine.transType == InventTransType::Sales && currentLine.expeditionStatus == WMSExpeditionStatus::Activated)
        {
            select firstonly RecId from wmsOrderTrans
                where wmsOrderTrans.routeId == currentLine.pickingRouteID
                exists join inventDim
                    where inventDim.inventDimId == wmsOrderTrans.inventDimId
                exists join inventLocation
                    where inventLocation.InventLocationId == inventDim.InventLocationId &&
                        inventLocation.METCSDWarehouse == NoYes::Yes;

            if (wmsOrderTrans.RecId)
            {
                canReviewSelection = true;
            }
            else
            {
                canReviewSelection = false;
            }
        }
        else
        {
            canReviewSelection = false;
        }

        currentLine = WMSPickingRouteDS.getNext();
    }

    ctrl.enabled(canReviewSelection);
}
